1	//! Validation for every write: one bounded claim, well-formed slots, and no
2	//! credentials. The secret check cannot be turned off; memories are meant
3	//! to be recalled into prompts, so a stored key would leak on every recall.
4	
5	use std::sync::LazyLock;
6	
7	use regex::Regex;
8	
9	use super::{Kind, Remember, Settings};
10	
11	/// A write refused before touching the database (exit status 2).
12	#[derive(Debug)]
13	pub struct Refused(pub String);
14	
15	impl std::fmt::Display for Refused {
16	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
17	        f.write_str(&self.0)
18	    }
19	}
20	
21	impl std::error::Error for Refused {}
22	
23	fn refuse<T>(msg: impl Into<String>) -> Result<T, Refused> {
24	    Err(Refused(msg.into()))
25	}
26	
27	static SECRETS: LazyLock<Vec<(&'static str, Regex)>> = LazyLock::new(|| {
28	    [
29	        ("private key", r"-----BEGIN [A-Z0-9 ]*PRIVATE KEY"),
30	        ("AWS access key", r"\b(?:AKIA|ASIA)[0-9A-Z]{16}\b"),
31	        ("GitHub token", r"\b(?:gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{30,})"),
32	        ("API key", r"\bsk-(?:ant-|proj-|live-)?[A-Za-z0-9_-]{20,}"),
33	        ("Slack token", r"\bxox[abposr]-[A-Za-z0-9-]{10,}"),
34	        ("Google API key", r"\bAIza[0-9A-Za-z_-]{35}"),
35	        ("Stripe key", r"\b[rsp]k_(?:live|test)_[0-9A-Za-z]{16,}"),
36	        ("npm token", r"\bnpm_[A-Za-z0-9]{36}\b"),
37	        ("crates.io token", r"\bcio[A-Za-z0-9]{32}\b"),
38	        ("JWT", r"\beyJ[A-Za-z0-9_-]{8,}\.eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}"),
39	        ("credentials in a URL", r"(?i)\b[a-z][a-z0-9+.-]*://[^\s/:@]+:[^\s/@]{3,}@"),
40	        (
41	            "password or key assignment",
42	            r#"(?i)\b(?:password|passwd|pwd|passphrase|secret|api[_-]?key|access[_-]?key|access[_-]?token|auth[_-]?token|client[_-]?secret|private[_-]?key|bearer)\b["']?\s*(?:[:=]|\bis\b)\s*["']?[^\s"']{6,}"#,
43	        ),
44	    ]
45	    .into_iter()
46	    .map(|(name, re)| (name, Regex::new(re).expect("secret pattern")))
47	    .collect()
48	});
49	
50	static LONG_TOKEN: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"[A-Za-z0-9+/_=-]{32,}").unwrap());
51	
52	/// What kind of credential `text` appears to contain, if any.
53	pub fn secret_kind(text: &str) -> Option<&'static str> {
54	    if let Some((name, _)) = SECRETS.iter().find(|(_, re)| re.is_match(text)) {
55	        return Some(name);
56	    }
57	    LONG_TOKEN.find_iter(text).any(|m| looks_random(m.as_str())).then_some("high-entropy token")
58	}
59	
60	/// Mixed-case alphanumerics with more entropy than hex can have: hashes and
61	/// ids (hex, base32) pass, base64 keys do not.
62	fn looks_random(token: &str) -> bool {
63	    let has = |f: fn(&char) -> bool| token.chars().any(|c| f(&c));
64	    if !(has(char::is_ascii_lowercase) && has(char::is_ascii_uppercase) && has(char::is_ascii_digit)) {
65	        return false;
66	    }
67	    let mut counts = [0u32; 128];
68	    for b in token.bytes() {
69	        counts[usize::from(b & 127)] += 1;
70	    }
71	    let n = token.len() as f64;
72	    let entropy: f64 =
73	        counts.iter().filter(|c| **c > 0).map(|c| f64::from(*c) / n).map(|p| -p * p.log2()).sum();
74	    entropy > 4.2
75	}
76	
77	static NAMESPACE: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"^[a-z0-9][a-z0-9:_./@-]{0,63}$").unwrap());
78	static KEY: LazyLock<Regex> =
79	    LazyLock::new(|| Regex::new(r"^[\p{Ll}\p{Lo}\p{N}][\p{Ll}\p{Lo}\p{N}_.:/@-]{0,79}$").unwrap());
80	static TAG: LazyLock<Regex> =
81	    LazyLock::new(|| Regex::new(r"^[\p{Ll}\p{Lo}\p{N}][\p{Ll}\p{Lo}\p{N}_.:/-]{0,39}$").unwrap());
82	
83	pub fn namespace(raw: &str) -> Result<String, Refused> {
84	    let ns = raw.trim().to_lowercase();
85	    if !NAMESPACE.is_match(&ns) {
86	        return refuse(format!(
87	            "namespace {raw:?}: use 1-64 of a-z 0-9 : _ . / @ -, e.g. `user`, `project:billing`, `agent:reviewer`"
88	        ));
89	    }
90	    Ok(ns)
91	}
92	
93	/// Slot names are lowercase; spaces become underscores.
94	pub fn key(raw: &str) -> Result<String, Refused> {
95	    let k = raw.split_whitespace().collect::<Vec<_>>().join("_").to_lowercase();
96	    if !KEY.is_match(&k) {
97	        return refuse(format!("key {raw:?}: use a short slot name like `editor` or `deploy.target`"));
98	    }
99	    Ok(k)
100	}
101	
102	fn one_line(s: &str) -> String {
103	    s.split_whitespace().collect::<Vec<_>>().join(" ")
104	}
105	
106	fn check_secret(field: &str, value: &str) -> Result<(), Refused> {
107	    match secret_kind(value) {
108	        Some(kind) => refuse(format!(
109	            "refused: the {field} looks like a credential ({kind}). Never store secrets in memory; \
110	             remember where the secret lives instead (for example \"deploy key is in the team vault\")"
111	        )),
112	        None => Ok(()),
113	    }
114	}
115	
116	/// A validated write.
117	pub(crate) struct Clean {
118	    pub ns: String,
119	    pub kind: Kind,
120	    pub subject: Option<String>,
121	    pub key: Option<String>,
122	    pub text: String,
123	    pub tags: Vec<String>,
124	    pub importance: u8,
125	    pub confidence: f64,
126	    pub source: Option<String>,
127	    pub refs: Vec<String>,
128	    pub pinned: bool,
129	    pub expires_at: Option<String>,
130	    pub aliases: Vec<String>,
131	}
132	
133	pub(crate) fn check(req: &Remember, settings: &Settings, now_secs: i64) -> Result<Clean, Refused> {
134	    let text = one_line(&req.text);
135	    if text.is_empty() {
136	        return refuse("`text` is empty: say the one thing to remember");
137	    }
138	    let chars = text.chars().count();
139	    if chars > settings.max_chars {
140	        return refuse(format!(
141	            "memory is {chars} characters; the cap is {}. Store one claim per memory: split it, or keep the \
142	             long version in a file and remember where it is",
143	            settings.max_chars
144	        ));
145	    }
146	    check_secret("text", &text)?;
147	
148	    let ns = namespace(req.ns.as_deref().unwrap_or(&settings.namespace))?;
149	    let subject = req.subject.as_deref().map(one_line).filter(|s| !s.is_empty());
150	    if let Some(s) = &subject {
151	        if s.chars().count() > 120 {
152	            return refuse(
153	                "subject is over 120 characters: name the person, project or thing, not a sentence",
154	            );
155	        }
156	        check_secret("subject", s)?;
157	    }
158	    let key = req.key.as_deref().map(str::trim).filter(|k| !k.is_empty()).map(key).transpose()?;
159	    if let Some(k) = &key {
160	        check_secret("key", k)?;
161	    }
162	
163	    let mut tags = Vec::new();
164	    for raw in &req.tags {
165	        let t = raw.split_whitespace().collect::<Vec<_>>().join("-").to_lowercase();
166	        if t.is_empty() || tags.contains(&t) {
167	            continue;
168	        }
169	        if !TAG.is_match(&t) {
170	            return refuse(format!("tag {raw:?}: use short words like `infra` or `billing`"));
171	        }
172	        check_secret("tag", &t)?;
173	        tags.push(t);
174	    }
175	    if tags.len() > 12 {
176	        return refuse("at most 12 tags");
177	    }
178	
179	    let mut refs: Vec<String> = Vec::new();
180	    for r in req.refs.iter().map(|r| one_line(r)).filter(|r| !r.is_empty()) {
181	        if r.chars().count() > 200 {
182	            return refuse("a ref is over 200 characters: refs are ids, paths or URLs");
183	        }
184	        check_secret("ref", &r)?;
185	        if !refs.contains(&r) {
186	            refs.push(r);
187	        }
188	    }
189	    if refs.len() > 20 {
190	        return refuse("at most 20 refs");
191	    }
192	
193	    let source = req.source.as_deref().map(one_line).filter(|s| !s.is_empty());
194	    if let Some(s) = &source {
195	        if s.chars().count() > 120 {
196	            return refuse("source is over 120 characters: say who or what it came from, briefly");
197	        }
198	        check_secret("source", s)?;
199	    }
200	
201	    let importance = req.importance.unwrap_or(3);
202	    if !(1..=5).contains(&importance) {
203	        return refuse("importance is 1 (trivia) to 5 (critical)");
204	    }
205	    let confidence = req.confidence.unwrap_or(1.0);
206	    if !(confidence.is_finite() && (0.0..=1.0).contains(&confidence)) {
207	        return refuse("confidence is between 0 and 1");
208	    }
209	    let expires_at = req
210	        .expires
211	        .as_deref()
212	        .map(str::trim)
213	        .filter(|e| !e.is_empty())
214	        .map(|e| expiry(e, now_secs))
215	        .transpose()?;
216	
217	    let mut aliases = Vec::new();
218	    for a in req.aliases.iter().map(|a| one_line(a)).filter(|a| !a.is_empty()) {
219	        if subject.is_none() {
220	            return refuse("`aliases` need a `subject` to point at");
221	        }
222	        if a.chars().count() > 120 {
223	            return refuse("an alias is over 120 characters");
224	        }
225	        aliases.push(a);
226	    }
227	
228	    Ok(Clean {
229	        ns,
230	        kind: req.kind.unwrap_or(if key.is_some() { Kind::Fact } else { Kind::Note }),
231	        subject,
232	        key,
233	        text,
234	        tags,
235	        importance,
236	        confidence,
237	        source,
238	        refs,
239	        pinned: req.pinned,
240	        expires_at,
241	        aliases,
242	    })
243	}
244	
245	/// `2026-12-31`, an RFC 3339 time, or a duration from now: `12h`, `30d`, `6w`.
246	pub(crate) fn expiry(raw: &str, now_secs: i64) -> Result<String, Refused> {
247	    let (num, unit) = raw.split_at(raw.find(|c: char| !c.is_ascii_digit()).unwrap_or(raw.len()));
248	    if let (Ok(n), Some(secs)) = (
249	        num.parse::<i64>(),
250	        match unit.trim() {
251	            "h" => Some(3600),
252	            "d" => Some(86_400),
253	            "w" => Some(7 * 86_400),
254	            _ => None,
255	        },
256	    ) {
257	        return Ok(crate::text::format_unix(now_secs + n.min(100_000) * secs));
258	    }
259	    match crate::text::normalize_date(raw) {
260	        Some(d) if d.len() == 10 => Ok(format!("{d}T23:59:59Z")),
261	        Some(d) => Ok(format!("{d}Z")),
262	        None => refuse(format!("expires {raw:?}: use a date (2026-12-31) or a duration (12h, 30d, 6w)")),
263	    }
264	}
265	
266	#[cfg(test)]
267	mod tests {
268	    use super::*;
269	
270	    #[test]
271	    fn secrets_are_caught_and_ordinary_text_is_not() {
272	        for s in [
273	            "token FIXTURE_REDACTED",
274	            "key FIXTURE_REDACTED",
275	            "FIXTURE_REDACTED is the deploy key",
276	            "password: hunter2hunter2",
277	            "the db password is Tr0ub4dor&3",
278	            "postgres://admin:s3cretpw@db.internal:5432/app",
279	            "-----BEGIN OPENSSH PRIVATE KEY-----",
280	            "x Zm9vYmFyYmF6cXV4MTIzNDU2Nzg5MEFCQ0RFRkdISUpL y",
281	        ] {
282	            assert!(secret_kind(s).is_some(), "missed: {s}");
283	        }
284	        for s in [
285	            "Prefers tabs over spaces and short commit messages",
286	            "deploys go through the staging cluster first",
287	            "commit 3f2a9c4e8b7d6a5f4e3d2c1b0a9f8e7d6c5b4a3f fixed the race",
288	            "memory m01j9zq4xk2m3n4p5 superseded the old value",
289	            "the password policy requires 12 characters",
290	            "API key rotation happens every 90 days",
291	        ] {
292	            assert_eq!(secret_kind(s), None, "false positive: {s}");
293	        }
294	    }
295	
296	    #[test]
297	    fn expiry_accepts_dates_and_durations() {
298	        assert_eq!(expiry("2026-12-31", 0).unwrap(), "2026-12-31T23:59:59Z");
299	        assert_eq!(expiry("2d", 0).unwrap(), "1970-01-03T00:00:00Z");
300	        assert!(expiry("soonish", 0).is_err());
301	    }
302	
303	    #[test]
304	    fn keys_and_namespaces_are_normalized() {
305	        assert_eq!(key(" Favorite Color ").unwrap(), "favorite_color");
306	        assert!(key("no;semicolons").is_err());
307	        assert_eq!(namespace("Project:Billing").unwrap(), "project:billing");
308	        assert!(namespace("*").is_err());
309	    }
310	}
