1	//! Model Context Protocol server (JSON-RPC 2.0). [`Session`] holds the tools;
2	//! [`serve`] runs it over stdio (one message per line) and `http` serves the
3	//! same session over Streamable HTTP.
4	//!
5	//! The data tools are read-only: fixed query shapes over the index, with no
6	//! SQL passthrough and no file access. Writes exist only for the opt-in
7	//! memory store (`--memory`), whose own file is the only thing they touch.
8	//! stdout carries protocol messages only; diagnostics go to stderr.
9	
10	use std::io::{self, BufRead, Write};
11	use std::path::PathBuf;
12	
13	use anyhow::{Result, bail};
14	use serde_json::{Value, json};
15	
16	use crate::card::CardOptions;
17	use crate::config::plural;
18	use crate::memory::{Forget, Kind, Memory, RecallRequest, Remember, Settings};
19	use crate::query::{AggregateRequest, Metric, Scope, SearchRequest, Sort, Store};
20	use crate::render;
21	
22	pub const PROTOCOL_VERSIONS: &[&str] = &["2025-11-25", "2025-06-18", "2025-03-26", "2024-11-05"];
23	
24	const DATA_INSTRUCTIONS: &str = "Leviathan searches a large indexed dataset and returns a few ranked, cited records instead of raw data. \
25	Call `describe` once to learn the fields, groups and filter values. Then use `search`: words for ranked matches, \
26	`group` to scope to one entity, `where` for exact filters, `since`/`until` for dates, no words for newest first. \
27	If a group is ambiguous, show the candidates and ask; never guess. Results marked OTHER come from a different group: say so. \
28	Use `get` only when the full record is needed.";
29	
30	const MEMORY_INSTRUCTIONS: &str = "Leviathan memory: call `recall` with no arguments once at the start of a session, and with \
31	words or a `subject` before acting on anything you may have learned before. `remember` durable facts, preferences, \
32	decisions (with the reason) and lessons, one claim each; give anything that can change a `key` and a `subject` so the \
33	next write replaces it. Never store secrets, credentials or transient state. Superseded memories are history, not truth.";
34	
35	const RECALL_ONLY_INSTRUCTIONS: &str = "Leviathan memory (read-only here): call `recall` with no arguments once at the start \
36	of a session, and with words or a `subject` before acting on anything you may have learned before.";
37	
38	/// Which memory tools a client gets.
39	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, clap::ValueEnum)]
40	pub enum MemoryTools {
41	    /// remember, recall, forget, memory_describe.
42	    #[default]
43	    All,
44	    /// recall and memory_describe only.
45	    Recall,
46	}
47	
48	#[derive(Debug, Clone)]
49	pub struct MemoryOptions {
50	    pub path: PathBuf,
51	    pub settings: Settings,
52	    pub tools: MemoryTools,
53	}
54	
55	#[derive(Debug, Clone)]
56	pub struct ServerOptions {
57	    pub index: PathBuf,
58	    pub card: CardOptions,
59	    pub memory: Option<MemoryOptions>,
60	}
61	
62	/// One line summarizing the open index, appended to tool descriptions so the
63	/// agent knows the data's shape before its first call.
64	fn dataset_summary(store: &Store) -> Option<String> {
65	    let d = store.describe(5).ok()?;
66	    let (record, group) = (&d.about.record, &d.about.group);
67	    let mut s = format!(
68	        "This index: {}{} {}",
69	        d.about.name.as_deref().map(|n| format!("{n}, ")).unwrap_or_default(),
70	        render::thousands(d.record_count),
71	        plural(record)
72	    );
73	    if !d.kinds.is_empty() {
74	        let kinds: Vec<String> = d
75	            .kinds
76	            .iter()
77	            .map(|k| {
78	                let group = k.fields.group.as_deref().map(|g| format!(", group = {g}")).unwrap_or_default();
79	                format!("{} ({} {}{group})", k.name, render::thousands(k.records), plural(&k.record))
80	            })
81	            .collect();
82	        s.push_str(&format!(
83	            " of {} kinds: {}. Ids are `<kind>:<id>`; `where _kind=<kind>` keeps one kind, `by: _kind` counts per kind",
84	            d.kinds.len(),
85	            kinds.join(", ")
86	        ));
87	    }
88	    if let Some(g) = &d.fields.group {
89	        s.push_str(&format!(" across {} {} (group = {g})", render::thousands(d.group_count), plural(group)));
90	    }
91	    if let (Some(a), Some(b)) = (&d.date_min, &d.date_max) {
92	        s.push_str(&format!(", dated {} to {}", render::day(a), render::day(b)));
93	    }
94	    if !d.filters.is_empty() {
95	        let parts: Vec<String> = d
96	            .filters
97	            .iter()
98	            .map(|f| {
99	                let vals: Vec<&str> = f.top.iter().take(4).map(|(v, _)| v.as_str()).collect();
100	                let more = if f.distinct > vals.len() as i64 { ", ..." } else { "" };
101	                format!("{} ({}{more})", f.field, vals.join(", "))
102	            })
103	            .collect();
104	        s.push_str(&format!(". Filters: {}", parts.join("; ")));
105	    }
106	    s.push('.');
107	    Some(s)
108	}
109	
110	fn format_param() -> Value {
111	    json!({"type": "string", "enum": ["text", "json"], "description": "text (default, fewest tokens) or json"})
112	}
113	
114	fn data_tools(store: Option<&Store>) -> Vec<Value> {
115	    let format = format_param();
116	    let mut search_desc = "Ranked records for free-text words (quote \"exact phrases\", -exclude words), optionally scoped \
117	        to one group, filtered by exact field values and a date range. With no words, lists newest first. Resolves the group \
118	        itself and returns candidates instead of guessing when it is ambiguous."
119	        .to_string();
120	    if let Some(summary) = store.and_then(dataset_summary) {
121	        search_desc = format!("{search_desc} {summary}");
122	    }
123	    vec![
124	        json!({
125	            "name": "search",
126	            "description": search_desc,
127	            "inputSchema": {
128	                "type": "object",
129	                "properties": {
130	                    "query": {"type": "string", "description": "Words to rank by. Omit to list newest first."},
131	                    "group": {"type": "string", "description": "Group key or name, as the user said it"},
132	                    "scope": {"type": "string", "enum": ["group", "others", "all"], "description": "With a group: group (default), others = every other group"},
133	                    "where": {"type": "object", "additionalProperties": {"anyOf": [{"type": "string"}, {"type": "array", "items": {"type": "string"}}]}, "description": "Exact filters, e.g. {\"status\": \"open\"}; an array means any of"},
134	                    "where_list": {"type": "array", "items": {"type": "string"}, "description": "Same filters as field=value strings, e.g. [\"status=open\"]"},
135	                    "since": {"type": "string", "description": "YYYY, YYYY-MM or YYYY-MM-DD"},
136	                    "until": {"type": "string", "description": "Inclusive, same formats"},
137	                    "sort": {"type": "string", "enum": ["relevance", "newest"]},
138	                    "limit": {"type": "integer", "minimum": 1, "maximum": 25, "description": "Default 5"},
139	                    "offset": {"type": "integer", "minimum": 0},
140	                    "format": format
141	                }
142	            },
143	            "annotations": {"readOnlyHint": true, "openWorldHint": false}
144	        }),
145	        json!({
146	            "name": "resolve_group",
147	            "description": "Group key or name to candidate groups (key, name, record count, how it matched).",
148	            "inputSchema": {
149	                "type": "object",
150	                "properties": {"query": {"type": "string"}, "limit": {"type": "integer", "minimum": 1, "maximum": 25}, "format": format},
151	                "required": ["query"]
152	            },
153	            "annotations": {"readOnlyHint": true, "openWorldHint": false}
154	        }),
155	        json!({
156	            "name": "get",
157	            "description": "One complete record by id, exactly as ingested.",
158	            "inputSchema": {"type": "object", "properties": {"id": {"type": "string"}}, "required": ["id"]},
159	            "annotations": {"readOnlyHint": true, "openWorldHint": false}
160	        }),
161	        json!({
162	            "name": "describe",
163	            "description": "The dataset's fields, groups, filter values with counts, date range and example calls.",
164	            "inputSchema": {"type": "object", "properties": {"format": format}},
165	            "annotations": {"readOnlyHint": true, "openWorldHint": false}
166	        }),
167	        json!({
168	            "name": "aggregate",
169	            "description": "Exact counts and totals over every matching record, from the index: how many, how many different, \
170	                which group has the most, per year or month, per any field, or two at once (group,month). Count records, \
171	                count distinct values of a field, or sum/avg/min/max a numeric field; keep only records meeting numeric \
172	                conditions (hours>4). Takes the same group, filters, words and dates as search. Use it instead of reading \
173	                or scanning the data for any question about how many, how much, or which most.",
174	            "inputSchema": {
175	                "type": "object",
176	                "properties": {
177	                    "by": {"type": "string", "description": "group, year, month, day, a filter field or any field (parts[].name); two comma-separated for a breakdown (group,month); omit for one total"},
178	                    "metric": {"type": "string", "enum": ["count", "distinct", "sum", "avg", "min", "max"], "description": "Default count; distinct counts different values of field"},
179	                    "field": {"type": "string", "description": "Field for distinct (any values) or sum/avg/min/max (numbers), e.g. labor[].tech or hours"},
180	                    "numeric": {"type": "array", "items": {"type": "string"}, "description": "Keep records whose number field compares: hours>4, total<=100 (> >= < <= = !=)"},
181	                    "group": {"type": "string", "description": "One group key or name"},
182	                    "group_contains": {"type": "string", "description": "Every group whose key or name contains this, e.g. a site or prefix"},
183	                    "where": {"type": "object", "additionalProperties": {"anyOf": [{"type": "string"}, {"type": "array", "items": {"type": "string"}}]}, "description": "Exact filters, as in search"},
184	                    "query": {"type": "string", "description": "Words the records must match (optional)"},
185	                    "since": {"type": "string", "description": "YYYY, YYYY-MM or YYYY-MM-DD"},
186	                    "until": {"type": "string", "description": "Inclusive, same formats"},
187	                    "limit": {"type": "integer", "minimum": 1, "maximum": 200, "description": "Rows to return, largest first; default 20"},
188	                    "format": format
189	                }
190	            },
191	            "annotations": {"readOnlyHint": true, "openWorldHint": false}
192	        }),
193	    ]
194	}
